#!/usr/bin/env node
/**
 * Create a single-file build that can be opened directly (file://).
 *
 * Browsers refuse to load ES modules from file://, so the normal Vite output
 * cannot run when double-clicked. The production bundle has no imports, so it
 * can be inlined as a classic script into one HTML file.
 *
 * Usage: npm run build:standalone
 * Output: dist/beambench-standalone.html
 */
import { readFileSync, writeFileSync, statSync } from 'node:fs';
import { resolve, dirname } from 'node:path';

const dist = resolve(process.cwd(), process.argv[2] || 'dist');
const htmlPath = resolve(dist, 'beambench.html');
const html = readFileSync(htmlPath, 'utf-8');

const scriptPattern = /<script[^>]*\bsrc="([^"]+)"[^>]*><\/script>/;
const match = html.match(scriptPattern);
if (!match) {
  throw new Error('No external script tag found in dist/beambench.html');
}

const relativeScript = match[1].replace(/^\//, '');
const scriptPath = resolve(dist, relativeScript);
let script = readFileSync(scriptPath, 'utf-8');

if (/\bimport\s*\(|\bimport\s+[\w{*]|\bexport\s+/.test(script)) {
  throw new Error('Bundle still contains module syntax; cannot inline as a classic script');
}

// The bundle must not terminate the surrounding <script> element.
script = script.replace(/<\/script/gi, '<\\/script');
script = script.replace(/\n?\/\/# sourceMappingURL=.*$/m, '');

const embedded = `<script>\n/* BeamBench standalone bundle — generated by tools/make-standalone.mjs */\n${script}\n</script>`;
// Vite puts the module tag in <head>; a classic inline script must run after
// the body exists, so remove the tag and append the bundle before </body>.
// Use a function so `$&`/`$'` sequences inside the bundle are kept verbatim.
let standalone = html.replace(match[0], () => '');
if (!standalone.includes('</body>')) {
  throw new Error('No </body> tag found in dist/beambench.html');
}
standalone = standalone.replace('</body>', () => `${embedded}\n</body>`);

const outPath = resolve(dist, 'beambench-standalone.html');
writeFileSync(outPath, standalone);
const size = statSync(outPath).size;
console.log(`Standalone build: ${outPath} (${(size / 1024 / 1024).toFixed(2)} MiB)`);
